        std::string user;
        std::cin >> user;
        registered.insert(user);
    }

    int q = 0;
    std::cin >> q;
    std::set<std::string> loggedIn;
    for (int i = 0; i < q; ++i) {
        std::string attempt;
        std::cin >> attempt;
