        }
    }
    std::cout << "logged in: " << loggedIn.size() << '\n';
    return 0;
}

steps.body:
When each input line is a record, give it a struct and read straight into its fields. `>>` works on members just like on plain variables:

```cpp harness
#include <bits/stdc++.h>

struct Player {
    std::string name;
    int age = 0;
    int score = 0;
};

int main() {
    int n = 0;
    std::cin >> n;
    std::vector<Player> players;
    for (int i = 0; i < n; ++i) {
        {{code}}
    }
    for (const Player& p : players) {
        std::cout << p.name << ' ' << p.age << ' ' << p.score << '\n';
    }
    return 0;
}
```

```stdin
4
mia 24 88
leo 31 95
ava 19 88
zed 27 70
```

```cpp
Player p;
std::cin >> p.name >> p.age >> p.score;
players.push_back(p);
```

The default member initializers (`int age = 0;`) mean `p` never holds garbage before the read. `push_back` copies the struct into the vector, which stores all its elements in one heap buffer. Each `std::string` inside keeps its own text.

Sort with a comparator lambda that compares the main key and falls back to a second key on ties, so the order never depends on input order:

```cpp harness
#include <bits/stdc++.h>

struct Player {
    std::string name;
    int age = 0;
    int score = 0;
};

int main() {
    std::vector<Player> players = {{"mia", 24, 88}, {"leo", 31, 95}, {"ava", 19, 88}, {"zed", 27, 70}};
    {{code}}
    for (const Player& p : players) {
        std::cout << p.name << ' ' << p.age << ' ' << p.score << '\n';
    }
    return 0;
}
```

```cpp
std::sort(players.begin(), players.end(), [](const Player& a, const Player& b) {
    if (a.score != b.score) {
        return a.score > b.score;
    }
    return a.name < b.name;
});
```

Take the parameters by `const&` so sorting does not copy every record on each comparison. Put the printing in a `const` member function such as `void print() const`. It promises not to change the object and works on `const` elements.

Fields read with `>>` are single words. A title with spaces would need `std::getline` and a delimiter instead.

example.code:
#include <algorithm>
#include <cstddef>
#include <iostream>
#include <string>
#include <vector>

struct Player {
    std::string name;
    int age = 0;
    int score = 0;

    void print() const {
        std::cout << name << ' ' << score << '\n';
    }
};

int main() {
    int n = 0;
    std::cin >> n;
    std::vector<Player> players;
    for (int i = 0; i < n; ++i) {
        Player p;
        std::cin >> p.name >> p.age >> p.score;
        players.push_back(p);
    }

    std::sort(players.begin(), players.end(), [](const Player& a, const Player& b) {
        if (a.score != b.score) {
            return a.score > b.score;  // higher score first
        }
        return a.name < b.name;  // ties: alphabetical
    });

    for (std::size_t i = 0; i < players.size(); ++i) {
        std::cout << i + 1 << ". ";
        players[i].print();
    }
    return 0;
}

