#include <algorithm>
#include <iomanip>
#include <iostream>
#include <string>
#include <vector>

struct Movie {
    std::string title;
    int year = 0;
    double rating = 0.0;

    void print() const {
        std::cout << year << ' ' << title << ' ' << rating << '\n';
    }
};

int main() {
    std::cout << std::fixed << std::setprecision(1);
    int n = 0;
    std::cin >> n;
    std::vector<Movie> movies;
    for (int i = 0; i < n; ++i) {
        Movie m;
        std::cin >> m.title >> m.year >> m.rating;
        movies.push_back(m);
    }

    std::sort(movies.begin(), movies.end(), [](const Movie& a, const Movie& b) {
        if (a.year != b.year) {
            return a.year < b.year;
        }
        return a.title < b.title;
    });

    for (const auto& m : movies) {
        m.print();
    }
    return 0;
}
